The core file tools appear to be available but not listed as deferred. Here's the `ErrorBoundary` component:

```tsx
// src/components/ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      if (fallback) return fallback(error, this.reset);

      return (
        <div role="alert" style={{ padding: "1.5rem", fontFamily: "sans-serif" }}>
          <h2 style={{ marginTop: 0 }}>Something went wrong</h2>
          <pre
            style={{
              background: "#f5f5f5",
              padding: "0.75rem",
              borderRadius: "4px",
              overflowX: "auto",
              fontSize: "0.875rem",
            }}
          >
            {error.message}
          </pre>
          <button
            onClick={this.reset}
            style={{
              marginTop: "0.75rem",
              padding: "0.5rem 1rem",
              cursor: "pointer",
            }}
          >
            Try again
          </button>
        </div>
      );
    }

    return children;
  }
}
```

**Usage:**

```tsx
// Basic — uses built-in fallback UI
<ErrorBoundary>
  <SomeComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={(error, reset) => (
  <MyErrorUI message={error.message} onRetry={reset} />
)}>
  <SomeComponent />
</ErrorBoundary>
```

**Key design decisions:**

- `getDerivedStateFromError` is static (required by React) — captures the error into state to trigger the fallback render.
- `componentDidCatch` logs both the error and the component stack trace so you know exactly where the failure occurred.
- The `reset` callback clears the error state, causing children to re-render from scratch — the retry mechanism.
- An optional `fallback` prop lets callers provide a custom UI; if omitted, the built-in fallback renders.
- `role="alert"` on the default fallback ensures screen readers announce the error.
